// M5a-1 (docs/WorldForgeV2Plan.md §M5, the M5a paragraph's open item; docs/evidence/worldforge_v2/m5a_red_green.txt
// L4 runs 4-5 and 8): on the live CivLabE0 world (Perlin 20260816, the civ box) hamlet 3 at (-7976, 2280), seed
// 939730262, is REFUSED by the M0 walkability gate when it is built from its MAP - one croft's door -> living route
// pinched by a 1-micro step at the floor just inside its west door (lot 2: local (24, 3), a 10 x 14 toft on the
// hillside, the footprint (27, 6) 6 x 8, the door facing -X, setback 3) - while the layout AS BUILT ({"legacy_layout":
// true}) on the same fresh world BUILDS it: 3 crofts, the gate 10 / 10. N = 1, on the engine. This file reproduces
// the live site HEADLESS, both arms:
//   - the same recipe (civRecipe: Perlin 20260816, worldforge + civ, 8 sites, region 2048, spacing 400 - the
//     version-1 hashes pinned by WorldForgeStressTest), the same site record, the same params through
//     WorldForgeBuildService::settlementParamsFor (era, tier, seed, the min corner, every arriving road as an
//     entry, the reuse fraction, the street axis) - the control adds legacy_layout only;
//   - the chunks around the site generated by the chunk manager's OWN streaming generator (the realizer samples it
//     for natural ground and water, the planner's samplers), inserted as resident chunks;
//   - the plan's units run in order on that world; the gate's verdict read from the plan (gateOutcome), the blocked
//     routes' pinches and a micro floor profile across each pinch printed for the diagnosis.
// Rig differences from the live world, stated: no flora (nothing to clear), no water runtime spans (the live rect
// is dry: [M5A-WATER-CHECK] 0 wet of 1280 on hamlet 3), no item-prop manager (no tableware, no firewood - kinematic
// props, outside the chunk occupancy the gate reads), no snapshots, no residency streaming, Debug. The template library
// and a PlacedObjectManager ARE wired (chain 76: without the manager no fixture is placed, and the live pinch is a
// bench and a table two cells inside the croft's west door - the furnisher is the live-only ingredient).
